"""Discord and Telegram webhook alerting module."""

from __future__ import annotations

import logging
from typing import Optional
import httpx
from config.settings import EnvironmentSecrets

logger = logging.getLogger(__name__)


class AlertNotifier:
    """Dispatches real-time incident and milestone alerts to Discord or Telegram."""

    def __init__(self, env: EnvironmentSecrets) -> None:
        self.env = env

    async def send_alert(self, message: str) -> None:
        """Send urgent notification via configured webhooks."""
        logger.info("Dispatching alert notification...")

        async with httpx.AsyncClient(timeout=10.0) as client:
            # 1. Discord Webhook
            if self.env.discord_webhook_url:
                try:
                    payload = {"content": message}
                    resp = await client.post(self.env.discord_webhook_url, json=payload)
                    if resp.status_code >= 400:
                        logger.error("Failed to post Discord alert: %s", resp.text)
                except Exception as e:
                    logger.exception("Discord alert dispatch error: %s", e)

            # 2. Telegram Bot
            if self.env.telegram_bot_token and self.env.telegram_chat_id:
                try:
                    tg_url = f"https://api.telegram.org/bot{self.env.telegram_bot_token}/sendMessage"
                    payload = {
                        "chat_id": self.env.telegram_chat_id,
                        "text": message,
                        "parse_mode": "Markdown",
                    }
                    resp = await client.post(tg_url, json=payload)
                    if resp.status_code >= 400:
                        logger.error("Failed to post Telegram alert: %s", resp.text)
                except Exception as e:
                    logger.exception("Telegram alert dispatch error: %s", e)

