def _is_valid_browser_binary(p: Path) -> bool:
    if not p.is_file() or not os.access(p, os.X_OK):
        return False
    try:
        header = p.open("rb").read(4)
        # Linux ELF binary or Windows PE binary
        if header.startswith(b"\x7fELF") or header.startswith(b"MZ"):
            return True
        # If it starts with shebang #!, it's a script, not a browser binary
        if header.startswith(b"#!"):
            return False
    except Exception:
        return False
    return False

