            ariaModal: el.getAttribute("aria-modal"),
            ariaHidden: el.getAttribute("aria-hidden"),
            ariaLabelledby: el.getAttribute("aria-labelledby"),
            style: el.getAttribute("style"),
            offsetParent: el.offsetParent !== null,
            computedDisplay: window.getComputedStyle(el).display,
            computedVisibility: window.getComputedStyle(el).visibility,
            innerHTMLSnippet: el.innerHTML.slice(0, 150)
        }));
    }''')
    print(f"Dialogs before click ({len(dialogs_before)}):")
    print(json.dumps(dialogs_before, indent=2))

    # 2. Find tweet
    tweet = page.locator('article[data-testid="tweet"]').first
    count = await page.locator('article[data-testid="tweet"]').count()
    print(f"Tweets count on timeline: {count}")
    if count == 0:
        print("Page title:", await page.title())
        content = await page.content()
        print("Page HTML snippet:", content[:1000])
        await bm.close()
        return

    reply_btn = tweet.locator('[data-testid="reply"]').first
    print("Found reply button, clicking...")
    await reply_btn.click()
    await asyncio.sleep(3)

    # 3. Dialogs after click
    dialogs_after = await page.evaluate('''() => {
        return Array.from(document.querySelectorAll('[role="dialog"]')).map(el => ({
            tagName: el.tagName,
            id: el.id,
            className: el.className,
            ariaModal: el.getAttribute("aria-modal"),
            ariaHidden: el.getAttribute("aria-hidden"),
            ariaLabelledby: el.getAttribute("aria-labelledby"),
            computedDisplay: window.getComputedStyle(el).display,
            computedVisibility: window.getComputedStyle(el).visibility,
            offsetParent: el.offsetParent !== null,
            hasTextarea: el.querySelector('[data-testid="tweetTextarea_0"]') !== null,
            testId: el.getAttribute("data-testid")
        }));
    }''')
    print(f"Dialogs after click ({len(dialogs_after)}):")
    print(json.dumps(dialogs_after, indent=2))

    # 4. Textarea and ancestry info
    textarea_info = await page.evaluate('''() => {
        const ta = document.querySelector('[data-testid="tweetTextarea_0"]');
        if (!ta) return { found: false };
        let p = ta;
        const ancestors = [];
        while (p && p !== document.body) {
            ancestors.push({
                tag: p.tagName,
                id: p.id,
                role: p.getAttribute("role"),
                testId: p.getAttribute("data-testid"),
                ariaModal: p.getAttribute("aria-modal"),
                ariaHidden: p.getAttribute("aria-hidden")
            });
            p = p.parentElement;
        }
        const buttons = Array.from(document.querySelectorAll("button")).filter(b => {
            const tid = b.getAttribute("data-testid") || "";
            return tid.includes("tweetButton") || tid.includes("reply");
        }).map(b => ({
            testId: b.getAttribute("data-testid"),
            ariaDisabled: b.getAttribute("aria-disabled"),
            disabled: b.disabled,
            tabIndex: b.tabIndex,
            text: b.innerText
        }));
        return {
            found: true,
            ancestors: ancestors.slice(0, 8),
            buttons: buttons
        };
    }''')
    print("Textarea & Button info:")
    print(json.dumps(textarea_info, indent=2))

    await bm.close()

if __name__ == "__main__":
    asyncio.run(inspect())

