"""CLI Client for sending commands to REPL Server."""

import argparse
import json
import sys
import httpx

SERVER_URL = "http://127.0.0.1:9229"

def send_command(payload: dict) -> dict:
    try:
        with httpx.Client(timeout=60.0) as client:
            resp = client.post(f"{SERVER_URL}/action", json=payload)
            if resp.status_code == 200:
                return resp.json()
            else:
                return {"status": "error", "code": resp.status_code, "text": resp.text}
    except Exception as e:
        return {"status": "error", "error": str(e)}

def main():
    parser = argparse.ArgumentParser(description="REPL Browser Client")
    parser.add_argument("--action", required=True, help="Action to execute")
    parser.add_argument("--url", default="", help="URL for goto/open")
    parser.add_argument("--selector", default="", help="CSS selector")
    parser.add_argument("--text", default="", help="Text to type")
    parser.add_argument("--key", default="", help="Key to press")
    parser.add_argument("--delta-y", type=int, default=600, help="Scroll delta Y")
    parser.add_argument("--human", action="store_true", default=True, help="Use human biometrics")
    parser.add_argument("--no-human", action="store_false", dest="human", help="Disable human biometrics")
    parser.add_argument("--timeout", type=int, default=15000, help="Timeout ms")
    parser.add_argument("--filename", default="", help="Screenshot filename")
    parser.add_argument("--script", default="", help="JavaScript to evaluate")

    args = parser.parse_args()

    payload = {"action": args.action}
    if args.url:
        payload["url"] = args.url
    if args.selector:
        payload["selector"] = args.selector
    if args.text:
        payload["text"] = args.text
    if args.key:
        payload["key"] = args.key
    if args.delta_y:
        payload["delta_y"] = args.delta_y
    payload["human"] = args.human
    if args.timeout:
        payload["timeout"] = args.timeout
    if args.filename:
        payload["filename"] = args.filename
    if args.script:
        payload["script"] = args.script

    result = send_command(payload)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

